function validate([target]) {
  if (!Number.isInteger(target)) return 'target must be an integer.';
  if (target === 0) return 'target is never 0.';
  if (target < -1000000000 || target > 1000000000) return 'target is between -10^9 and 10^9.';
  return null;
}

