function reachNumber(target) {
  const goal = Math.abs(target);
  let moves = Math.ceil((Math.sqrt(8 * goal + 1) - 1) / 2);
  let sum = (moves * (moves + 1)) / 2;

  while (sum < goal || (sum - goal) % 2 !== 0) {
    moves++;
    sum += moves;
  }
  return moves;
}

