function reachNumber(target) {
  // Try every move count in turn and build an actual walk: start all moves to the right,
  // then turn around the largest moves that fit into half of the overshoot.
  const distance = Math.abs(target);
  for (let k = 1; ; k++) {
    const total = (k * (k + 1)) / 2;
    if (total < distance) continue;
    let toFlip = (total - distance) / 2;
    let position = 0;
    for (let step = k; step >= 1; step--) {
      if (step <= toFlip) {
        toFlip -= step;
        position -= step;
      } else {
        position += step;
      }
    }
    if (position === distance) return k;
  }
}

